-- =====================================================================
-- Acredit – import STANDARDE ANMCS, ediția a II-a (2018), din fișierul
-- EDITIA_A_II_STANDARDE_2018_7.xlsx: 17 standarde, 71 de criterii,
-- 183 de cerințe, 802 indicatori.
--
-- Rulează O SINGURĂ DATĂ în Supabase: SQL Editor → New query → lipește tot → Run.
-- Ce face:
--   1. adaugă coloanele pentru standard / criteriu / cerință;
--   2. șterge cerințele și întrebările DEMONSTRATIVE (și evaluările lor);
--   3. încarcă standardele reale și întrebările de simulare.
-- Poate fi rulat din nou fără probleme: actualizează, nu dublează.
--
-- Codurile indicatorilor (ex. S1.2-C3-R1-I2 = Standardul 1.2, criteriul 3,
-- cerința 1, indicatorul 2) sunt NUMEROTARE INTERNĂ a aplicației, după ordinea
-- din fișier. Nu sunt codurile din listele de verificare ANMCS (ex. 02.05.03.01.01).
-- =====================================================================

begin;

alter table public.requirements
  add column if not exists standard_code text,
  add column if not exists standard_name text,
  add column if not exists criterion text,
  add column if not exists cerinta text;

delete from public.requirements where code like 'DEMO-%';
delete from public.sim_questions where code like 'SIM-%';
delete from public.sections s
  where s.code in ('A', 'B', 'C')
    and not exists (select 1 from public.requirements r where r.section_id = s.id);

insert into public.sections (code, name, sort) values
  ('1', 'Managementul strategic și organizațional', 1),
  ('2', 'Managementul clinic', 2),
  ('3', 'Etica medicală și drepturile pacientului', 3)
on conflict (code) do update set name = excluded.name, sort = excluded.sort;

with std as (
  select s.value as s, s.ordinality as sn
  from jsonb_array_elements($JSON$[{"c":"1.1","d":"1","n":"Strategia şi managementul strategic al organizației sunt concordante cu nevoia de îngrijiri de sănătate și cu dinamica pieţii de servicii de sănătate.","r":[{"n":"Strategia (Planul strategic) se bazează pe analiza nevoilor de îngrijire ale populaţiei şi a pieţei de servicii.","e":[{"n":"Organizația a realizat (a utilizat) o analiză privind nevoile de îngrijire a populației căreia de adresează şi a pieței de servicii de sănătate din localitate/județ.","i":[{"k":"S1.1-C1-R1-I1","t":"Analiza documentată privind nevoile de îngrijire a populației şi piaţa serviciilor de sănătate din localitate/județ, existentă."},{"k":"S1.1-C1-R1-I2","t":"Numărul de indicatori calitativi utilizați în analiza nevoilor de îngrijire ale populaţiei și a pieței de servicii."}]},{"n":"Rezultatele analizei privind nevoile de îngrijire a populaţiei și piața de servicii se regăsesc în formularea obiectivelor strategice ale spitalului","i":[{"k":"S1.1-C1-R2-I1","t":"Nevoile de îngrjire ale comunităţii deservite, identificate în cuprinsul analizei ."},{"k":"S1.1-C1-R2-I2","t":"Obiectivele stabilite în cuprinsul strategiei (Planului strategic), concordante cu nevoile de îngrijire a populației rezultate din analiză."}]}]},{"n":"Strategia (Planul strategic) elaborată de către organizație este asumată la toate nivelurile de decizie.","e":[{"n":"Strategia (Planul strategic) organizației este integrată în strategia de dezvoltare locală și regională și în concordanță cu Strategia din Sănătate.","i":[{"k":"S1.1-C2-R1-I1","t":"Obiectivele stabilite în strategie (Planul strategic), corelate cu obiectivele strategiei la nivel județean/regional și național."}]},{"n":"Strategia (Planul strategic) este formalizată, aprobată și cunoscută la nivelul organizației.","i":[{"k":"S1.1-C2-R2-I1","t":"Documentul formalizat privind strategia (Planul strategic), existent."},{"k":"S1.1-C2-R2-I2","t":"Documentul emis de către autoritatea tutelară privind aprobarea strategiei (Planului strategic), existent și conform."},{"k":"S1.1-C2-R2-I3","t":"Tabele cu semnăturile de luare la cunoștință ale responsabililor sectoarelor de activitate, existente."}]}]},{"n":"Strategia se implementează cu participarea tuturor sectoarelor de activitate.","e":[{"n":"La nivelul organizației există o echipă responsabilă cu evaluările periodice (Comitet director etc.) activă .","i":[{"k":"S1.1-C3-R1-I1","t":"Decizia de constituire a echipei responsabile, existentă."},{"k":"S1.1-C3-R1-I2","t":"Frecvența întâlnirilor echipei responsabile, stabilită."},{"k":"S1.1-C3-R1-I3","t":"Rapoarte periodice de analiză ale echipei responsabile adresate conducerii, existente."}]},{"n":"Şefii tuturor sectoarelor de activitate analizează periodic nivelul de realizare a obiectivelor strategice.","i":[{"k":"S1.1-C3-R2-I1","t":"Indicatori de analiză a gradului de implementare a strategiei (Planului strategic), stabiliți."},{"k":"S1.1-C3-R2-I2","t":"Procese-verbale/ rapoarte de analiză periodică privind gradul de realizare a obiectivelor strategice, existente."},{"k":"S1.1-C3-R2-I3","t":"Propuneri ale șefilor sectoarelor de activitate, consemnate (în procesele-verbale/rapoartele de analiză)."},{"k":"S1.1-C3-R2-I4","t":"Gradul de realizare a obiectivelor strategice, analizat periodic de către autoritatea tutelară."}]},{"n":"Planificarea anuală a activităţilor are în vedere obiectivele strategice stabilite.","i":[{"k":"S1.1-C3-R3-I1","t":"Planurile anuale ale organizației, existente."},{"k":"S1.1-C3-R3-I2","t":"Obiectivele stabilite în planurile anuale, corelate cu obiectivele strategice."},{"k":"S1.1-C3-R3-I3","t":"Obiective stabilite pentru fiecare sector de activitate, corelate cu obiectivele din Planurile anuale."},{"k":"S1.1-C3-R3-I4","t":"Grafic Gant de desfășurare a activităților pentru fiecare dintre sectoarele de activitate, existent și respectat."},{"k":"S1.1-C3-R3-I5","t":"Obiectivele stabilite pentru fiecare sector de activitate, îndeplinite în ultimul an calendaristic încheiat ."},{"k":"S1.1-C3-R3-I6","t":"Proiectele de dezvoltare inițiate sau aflate în derulare la nivelul organizației, corelate cu obiectivele strategice asumate."}]}]},{"n":"Strategia vizează îmbunătăţirea calităţii serviciilor şi siguranţa pacienţilor.","e":[{"n":"Prin strategie, s-a impus, ca prioritate, îmbunătăţirea calităţii şi a siguranţei pacienţilor la nivel de organizaţie.","i":[{"k":"S1.1-C4-R1-I1","t":"Minim 1 obiectiv strategic privind calitatea serviciilor si siguranta pacientilor, fundamentat in cuprinsul strategiei (Planului strategic)."},{"k":"S1.1-C4-R1-I2","t":"Parteneriate şi/sau convenţii cu alte organizaţii/instituţii medicale sau medico-sociale, locale, judeţene sau naţionale, implementate ."},{"k":"S1.1-C4-R1-I3","t":"Numărul angajaților care au participat la cursuri, programe de formare/perfecționare în domeniul calității serviciilor/Numărul total de angajați."},{"k":"S1.1-C4-R1-I4","t":"Ghiduri și protocoale utilizate în practica medicală, pentru realizarea obiectivelor strategice privind calitatea."}]}]}]},{"c":"1.2","d":"1","n":"Structura și managementul organizațional asigură derularea optimă a tuturor proceselor de acordarea a asistenţei şi îngrijirilor medicale.","r":[{"n":"Structura organizatorică este documentată, analizată şi după caz, actualizată periodic.","e":[{"n":"Documentele privind structura organizatorică aprobate şi în termen de valabilitate.","i":[{"k":"S1.2-C1-R1-I1","t":"Documentul privind structura, organigrama și statul de funcții, aprobate și corelate."},{"k":"S1.2-C1-R1-I2","t":"ROF și RI existente și conforme."}]},{"n":"Conducerea evalueaza periodic structura organizației în raport cu cererea de servicii de ingrijire a sanatatii populatiei.","i":[{"k":"S1.2-C1-R2-I1","t":"Indicatorii de utilizare a serviciilor, existenți și actualizați anual în contractul de management și contractele de administrare."},{"k":"S1.2-C1-R2-I2","t":"Indicatorii de utilizare a serviciilor din contractul de amangement și contractele de administrare, analizați cel puțin semestrial."},{"k":"S1.2-C1-R2-I3","t":"Procese-verbale/rapoarte de analiză a structurii și cererii de îngrijiri, existente."}]},{"n":"Conducerea analizează periodic modul de desfăşurare a proceselor de la nivelul organizației şi actualizează în consecinţă structura organizatorică.","i":[{"k":"S1.2-C1-R3-I1","t":"Indicatorii de performanță a unității, existenți și actualizați anual în contractul de management și contractele de administrare."},{"k":"S1.2-C1-R3-I2","t":"Indicatorii de performanță a unității din contractul de amangement și contractele de administrare, analizați cel puțin semestrial."},{"k":"S1.2-C1-R3-I3","t":"Documentele privind eventualele măsuri de modificare a structurii adoptate în consecința analizelor periodice, existente."}]}]},{"n":"Politica de resurse umane este documentată şi adaptată nevoilor privind organizarea și funcționarea unității.","e":[{"n":"Conducerea spitalului stabileşte necesarul de personal în raport cu volumul de activitate, din perspectiva optimizării procesului de furnizare a serviciilor.","i":[{"k":"S1.2-C2-R1-I1","t":"Structura şi distribuţia personalului (categorii şi număr), analizată periodic."},{"k":"S1.2-C2-R1-I2","t":"Decizii privind redistribuirea personalului, ca rezultat al analizelor periodice."},{"k":"S1.2-C2-R1-I3","t":"Volumul de activitate (ture, gărzi, program prelungit, mediu cu noxe etc) asigurat prin repartizarea echilibrată a personalului pe toate sectoarele."}]},{"n":"Conducerea organizației analizează anual structura posturilor și dispune măsuri pentru adaptarea acesteia la nevoile identificate.","i":[{"k":"S1.2-C2-R2-I1","t":"Analiza anuală a structurii posturilor."},{"k":"S1.2-C2-R2-I2","t":"Decizii privind măsurile dispuse ca urmare a analizei anuale."}]},{"n":"Conducerea organizației asigură elaborarea şi implementarea unui Plan anual de selecţie, recrutare şi dezvoltare profesională a personalului.","i":[{"k":"S1.2-C2-R3-I1","t":"Plan anual de selecţie şi recrutare, implementat."},{"k":"S1.2-C2-R3-I2","t":"Numărul posturilor scoase la concurs/Numărul total de posturi vacante (inclusiv temporar vacante), în ultimul an calendaristic încheiat."},{"k":"S1.2-C2-R3-I3","t":"Plan anual de dezvoltare profesională, implementat."},{"k":"S1.2-C2-R3-I4","t":"Parteneriate/convenții cu instituții sau organizații autorizate pentru susținerea programelor de formare și dezvoltare profesională, implementate."},{"k":"S1.2-C2-R3-I5","t":"Numărul angajaților care au participat la cursuri, programe de dezvoltare profesională/Numărul total de angajați, în ultimul an calendaristic încheiat."}]}]},{"n":"Structurile functionale de la nivelul unității (comisii, comitete, consilii) sunt constituite si operationale, asigurand integrarea proceselor si consolidarea controlului intern.","e":[{"n":"Structurile functionale de la nivelul unității (comisii, comitete, consilii) sunt constituite și active.","i":[{"k":"S1.2-C3-R1-I1","t":"Decizii de constituire existente și actualizate."},{"k":"S1.2-C3-R1-I2","t":"ROF ale structurilor funcționale (comisii, comitete și consilii) existente si implementate (sau existența distinctă a secțiunilor specifice în ROF-ul unității)."},{"k":"S1.2-C3-R1-I3","t":"Fişele de post ale personalului, membrii în structurile funcționale (comisii, comitete, consilii) actualizate."}]},{"n":"Activitatea structurilor funcționale (comisii, comitete și consilii) de la nivelul unității asigură fundamentarea procesului decizional.","i":[{"k":"S1.2-C3-R2-I1","t":"Activitatea desfasurată de structurile funcționale (comisii, comitete și consilii) de la nivelul unității înregistrată (consemnată) și accesibilă."},{"k":"S1.2-C3-R2-I2","t":"Decizii care au la bază rezultatele activității (propunerile) structurilor funcționale (comisii, comitete și consilii) de la nivelul unității, existente și implementate."}]}]},{"n":"Unitatea deține toate autorizatiile specifice și avizele, actualizate după caz.","e":[{"n":"Unitatea deține toate autorizatiile specifice și avizele, actualizate după caz.","i":[{"k":"S1.2-C4-R1-I1","t":"Autorizațiile specifice, existente și actualizate."},{"k":"S1.2-C4-R1-I2","t":"Avizele specifice, existente și în termen de valabilitate."},{"k":"S1.2-C4-R1-I3","t":"Documentele justificative pentru autorizațiile sau avizele aflate pe circuitul de aprobare, după caz."}]}]},{"n":"Procesul decizional de la toate nivelele de mangement, are în vedere condiţiile specifice de organizare si functionare ale unității.","e":[{"n":"Conducerea unității asigura participarea angajaților la procesul decizional si documentarea corecta a acestuia.","i":[{"k":"S1.2-C5-R1-I1","t":"Documente justificative pentru luarea deciziilor, existente și accesibile."},{"k":"S1.2-C5-R1-I2","t":"Existenta deciziilor formalizate și corelate cu documentele justificative."},{"k":"S1.2-C5-R1-I3","t":"Registru pentru înregistrarea deciziilor, existent și la zi."}]},{"n":"Procesul decizional se desfășoară în condiții de transparență.","i":[{"k":"S1.2-C5-R2-I1","t":"Documente justificative privind consultarea șefilor sectoarelor de activitate și a reprezentanților angajaților în procesul decizional."},{"k":"S1.2-C5-R2-I2","t":"Deciziile aplicabile activității, cunoscute de către angajații implicați în desfășurarea acesteia."}]}]},{"n":"Unitatea are organizat și funcțional un sistem de control managerial intern.","e":[{"n":"Comisia de control managerial intern este constituită și activă.","i":[{"k":"S1.2-C6-R1-I1","t":"Decizia de constituire a Comisiei de control managerial intern, existentă și implementată."},{"k":"S1.2-C6-R1-I2","t":"Fișele de post ale angajaților, membrii ai Comisiei de control managerial intern, actualizate."},{"k":"S1.2-C6-R1-I3","t":"Procedurile de sistem de la nivelul unității, avizate de Comisia de control managerial intern."},{"k":"S1.2-C6-R1-I4","t":"Registrul riscurilor de la nivelul unității, avizat de către Comisia de control managerial intern."}]}]}]},{"c":"1.3","d":"1","n":"Managementul financiar şi administrativ răspunde obiectivelor strategice şi operaţionale ale spitalului","r":[{"n":"Bugetul de venituri si cheltuieli al spitalului sustine realizarea planului anual de servicii","e":[{"n":"Bugetul este întocmit prin fundamentarea cheltuielilor","i":[{"k":"S1.3-C1-R1-I1","t":"Şefii sectoarelor de activitate fac propuneri de fundamentare a cheltuielilor"},{"k":"S1.3-C1-R1-I2","t":"Previziunile bugetare de venituri şi cheltuieli şi planul de investiţii sunt în conformitate cu obiectivele înscrise în strategie"},{"k":"S1.3-C1-R1-I3","t":"Planificarea cheltuielilor este în concordanţă cu planul anual de servicii şi cu planul anual de achiziţii"}]},{"n":"Spitalul analizează periodic veniturile realizate","i":[{"k":"S1.3-C1-R2-I1","t":"Există o analiză a veniturilor realizate în funcţie de tipul/numărul/ complexitatea serviciilor planificate"},{"k":"S1.3-C1-R2-I2","t":"Analiza simultană atât a costurilor cât şi a veniturilor realizate - la nivel de spital, la nivel de secţii şi compartimente şi la nivel de pacient"},{"k":"S1.3-C1-R2-I3","t":"Masuri implementate in urma analizei efectuate"}]},{"n":"Spitalul asigură realizarea planului anual de investiţii conform bugetului","i":[{"k":"S1.3-C1-R3-I1","t":"Investiţii realizate conform planului anual"},{"k":"S1.3-C1-R3-I2","t":"Concordanţa dintre valoarea investiţiei şi bugetul alocat"}]}]},{"n":"Bugetul este actualizat periodic din perspectiva eficientizarii procesului de furnizarea a serviciilor","e":[{"n":"Analiza periodică a procesului de furnizare a serviciilor cu participarea tuturor nivelurilor de management","i":[{"k":"S1.3-C2-R1-I1","t":"Indicatori de performanţă financiară asumaţi la toate nivelurile de management"},{"k":"S1.3-C2-R1-I2","t":"Analiza periodică a costurile în vederea eficientizării cheltuielilor"}]},{"n":"Adoptarea măsurilor de ajustare în funcţie de rezultatele analizei","i":[{"k":"S1.3-C2-R2-I1","t":"Plan de măsuri de ajustare"}]}]},{"n":"Asigurarea continuitatii in aprovizionarea sectoarelor de activitate","e":[{"n":"Spitalul întocmeşte şi actualizează lista produselor şi serviciilor critice","i":[{"k":"S1.3-C3-R1-I1","t":"Lista produselor şi serviciilor critice"}]},{"n":"Spitalul realizează analiza periodică a stocurilor","i":[{"k":"S1.3-C3-R2-I1","t":"Metodologie privind gestiunea stocurilor"},{"k":"S1.3-C3-R2-I2","t":"Responsabil desemnat cu analiza stocurilor"},{"k":"S1.3-C3-R2-I3","t":"Activitatea de reinnoire a stocurilor pentru produse critice este procedurata"}]},{"n":"Spitalul monitorizeaza functionalitatea serviciilor critice","i":[{"k":"S1.3-C3-R3-I1","t":"Contracte de furnizare a serviciilor critice, valabile în momentul evaluării"}]},{"n":"Aprovizionarea sectoarelor de activitate este corelată cu consumul","i":[{"k":"S1.3-C3-R4-I1","t":"Concordanţa dintre calitatea şi cantitatea produselor şi serviciilor solicitate şi a celor recepţionate"},{"k":"S1.3-C3-R4-I2","t":"Graficul de aprovizionare a sectoarelor de activitate cu produse şi servicii"}]},{"n":"Spitalul asigură aprovizionarea cu produse şi servicii pentru cazuri exceptionale","i":[{"k":"S1.3-C3-R5-I1","t":"Aprovizionarea în situaţii exceptionale este procedurată"}]}]}]},{"c":"1.4","d":"1","n":"Sistemul informaţional este organizat pentru a raspunde nevoilor de colectare a datelor si partajare eficace si eficienta a informatiior in mediul intern si extern","r":[{"n":"Sistemul de informaţii corespunde necesităţilor instituţiei","e":[{"n":"Proiectarea sistemului informaţional a luat in calcul nevoile informationale ale tuturor sectoare de activitate si solicitarile externe (formale sau informale)","i":[{"k":"S1.4-C1-R1-I1","t":"Planul de dezvoltare al sistemului informational cuprinde descrierea necesarului de resurse informationale, de acces la tehnologia informationala si de comunicatii pentru toata activitatea desfasurata"},{"k":"S1.4-C1-R1-I2","t":"Sefii sectoarelor de activitate sunt implicati in definirea nevoilor informationale ale organizatiei"},{"k":"S1.4-C1-R1-I3","t":"Scalabilitatea si complexitatea solutiilor de tehnologizare implementate sunt documentate in Planul de dezvoltare al sistemului informational si acopera toate structurile organizatiei"}]},{"n":"Factorii decizionali asigura cadrul aplicarii principiilor de utilizare si manageriere a informatiilor;","i":[{"k":"S1.4-C1-R2-I1","t":"Evaluarea si compararea efectelor cantitative si calitative ale sistemului informational cu costurile realizarii si functionarii lui realizata constant"},{"k":"S1.4-C1-R2-I2","t":"Interoperabilitatea informationala este definita in Planul de dezvoltare al sistemului informational astfel incat datele privind activitatea medicală, cele privind activitatea economico - finaciară și cea administrativă să permită realizarea unui „tablou de bord” care sa sustina actul decizional"}]}]},{"n":"La nivelul spitalului sunt reglementate proprietatea, confidentialitatea, integritatea si securitatea datelor","e":[{"n":"Politica spitalului privind securitatea datelor respecta legislatia in vigoare","i":[{"k":"S1.4-C2-R1-I1","t":"Unitatea este inregistrata ca operator de date cu caracter personal"},{"k":"S1.4-C2-R1-I2","t":"Politica de Securitate a Sistemului Informational reglementeaza modalitatea prin care proprietatea datelor este asigurata in raport cu terti colaboratori"}]},{"n":"Accesul la informatii, prelucrarea si protectia acestora sunt reglementate pentru fiecare categorie profesionala","i":[{"k":"S1.4-C2-R2-I1","t":"Regulamentul intern prevede conditiile in care salariatii sau fostii salariati au voie sa utilizeze sau sa transmita date"},{"k":"S1.4-C2-R2-I2","t":"Contractele individuale de munca au prevazuta clauza de confidentialitate asupra gestionarii informatiilor"},{"k":"S1.4-C2-R2-I3","t":"Regulament/procedura de asignare a accesului la informatii pe categorii profesionale si pentru fiecare persoana angajata in parte indiferent de categoria in care se incadreaza, implementata"},{"k":"S1.4-C2-R2-I4","t":"Activitatea de acces si utilizare a informatiilor procedurata pe tipuri de informatii si scopul utilizarii"},{"k":"S1.4-C2-R2-I5","t":"Integritatea informatiilor asigurata prin utilizarea filtrelor de verificare succesive"}]},{"n":"Monitorizarea respectarii prevederilor legiferate intern si extern cu privire securitatea informatiilor","i":[{"k":"S1.4-C2-R3-I1","t":"Programul anual de audit intern al spitalului cuprinde tematici cu privire la securitatea informatiilor"},{"k":"S1.4-C2-R3-I2","t":"Plan de măsuri tehnice şi organizatorice adecvate pentru protejarea și arhivarea datelor (fizic și electronic) cu caracter personal și medical (împotriva distrugerii accidentale sau ilegale, pierderii, modificării, dezvăluirii sau accesului neautorizat, inclusiv accesul fizic la server, precum şi împotriva oricărei alte forme de prelucrare ilegală), revizuit anual"}]}]},{"n":"Spitalul are un sistem standardizat de culegere al informatiilor","e":[{"n":"Documentele sunt concepute intr-o forma unitara si sunt complet asumate","i":[{"k":"S1.4-C3-R1-I1","t":"Spitalul are un sistem de management al documentelor implementat"},{"k":"S1.4-C3-R1-I2","t":"Documentelor utilizate in spital au prevazut un mecanism de aprobare si asumare pe nivele de competenta"}]},{"n":"Spitalul are un sistem standardizat de inregistrare a pacientilor.","i":[{"k":"S1.4-C3-R2-I1","t":"Identificarea si localizarea unui pacient in spital se face pe baza unui cod unic alocat pacientului"},{"k":"S1.4-C3-R2-I2","t":"Transmiterea Buletinelor de analiza si/sau investigatii se realizeaza pastrand confidentialitatea rezultatelor"},{"k":"S1.4-C3-R2-I3","t":"Sistemul de codificare (coduri de diagnostic, proceduri, simboluri, definitii, etc ) respecta reglementarile nationale"}]}]},{"n":"Tehnologiile medicale dedicate gestionarii datelor sunt evaluate periodic si sunt testate inaintea implementarii","e":[{"n":"Functia de administrare a sistemului informatic este asigurata","i":[{"k":"S1.4-C4-R1-I1","t":"Administratorul de sistem informatic asigura managementul conturilor de utilizatori pentru aplicatiile informatice, conform reglementarilor interne"},{"k":"S1.4-C4-R1-I2","t":"Numarul de utilizatori activi ai sistemului informatic inscrisi in evidentele administratorului de sistem/Nr. total personal (inclusiv medici rezidenti)"},{"k":"S1.4-C4-R1-I3","t":"Fiecare utilizator al Sistemului informatic poate sa-si gestioneze din contul sau propria parola"},{"k":"S1.4-C4-R1-I4","t":"Administratorul de sistem tine în permanenţă o listă actualizată a tuturor echipamentelor hardware din sistem si a licentelor pentru componentele software"},{"k":"S1.4-C4-R1-I5","t":"Mediile de stocare (serverele pe care se stochează informatiile) se află în spaţii securizate, protejate de măsuri de securitate fizică (DA/NU)"},{"k":"S1.4-C4-R1-I6","t":"Numarul de licente pentru sisteme de operare server active/Numarul de servere care deservesc sistemul informatic si de comunicatii (valoare numerica )"},{"k":"S1.4-C4-R1-I7","t":"Numarul de licente valide si active pentru sistemele de operare, ex. Windows ulterior XP/Numarul de sisteme de calcul disponibile (valoare numerica)"},{"k":"S1.4-C4-R1-I8","t":"Mentenanta sistemului informatic este asigurata pentru fiecare componenta (software, hardware si de comunicatii)"}]},{"n":"Sefii sectoarelor de activitate sunt implicati in alegerea, implementarea si evaluarea tehnologiilor medicale;","i":[{"k":"S1.4-C4-R2-I1","t":"Raportul anual de audit intern pe sistemul informational cuprinde constatarile si recomandarile utilizatorilor tehnologiilor informationale"},{"k":"S1.4-C4-R2-I2","t":"Exista implementat un portal (intern, tip help - desk, forum) prin care utilizatorii pot semnala problemele pe care le intampina in utilizarea sistemului informatic, pot propune imbunatatiri, emite pareri, etc"}]},{"n":"Tehnologiile medicale sunt analizate si testate inaintea implementarii, cu asigurarea confidentialitatii si securitatii datelor","i":[{"k":"S1.4-C4-R3-I1","t":"Documentul justificativ elaborat pentru implementarea fiecarei componente a sistemului informatic cuprinde informatii cu privire la valorile parametrilor de functionare in faza de testare a aplicatiilor"}]},{"n":"Tehnologiile medicale sunt evaluate periodic din punct de vedere al utilitatii, eficientei si sigurantei pacientului.","i":[{"k":"S1.4-C4-R4-I1","t":"Exista un model de chestionar pentru masurarea gradului de satisfactie in utilizarea sistemului informatic implementat"},{"k":"S1.4-C4-R4-I2","t":"Utilizarea chestionarelor si macheteleor privind implementarea si evaluarea tehnologiilor medicale este o tehnica uzuala in auditarea sistemului informatic"}]}]},{"n":"Culegerea si pastrarea informatiilor asigura protectia impotriva accesului, manipularii, utilizarii neautorizate si a pierderii sau distrugerii acestora","e":[{"n":"Documentele privind pacientii aflati intr-un proces de evaluare si/sau tratare sunt pastrate doar in zone cu acces restrictionat si in conditii corespunzatoare","i":[{"k":"S1.4-C5-R1-I1","t":"Procedura de gestiune a FOCG mentioneaza explicit locul de pastrare a documentelor medicale ca fiind o zona cu acces numai pentru personalul medical"},{"k":"S1.4-C5-R1-I2","t":"Pentru pacientii cu afectiuni cronice aflati in evidenta spitalului exista organizat un fisier separat cu acces restrictionat pentru personalul medical"},{"k":"S1.4-C5-R1-I3","t":"Zonele in care se pastreaza FOCG-urile pe perioada spitalizarii sunt prevazute cu spatii special amenajate pentru pastrarea documentelor medicale"}]},{"n":"Spitalul asigura sisteme de back-up","i":[{"k":"S1.4-C5-R2-I1","t":"Aplicatiile informatice sunt prevazute cu sisteme automate de back-up al bazelor de date"},{"k":"S1.4-C5-R2-I2","t":"Back-up functional pentru sistemul informatic"}]},{"n":"Spitalul asigura controlul utilizarii sistemelor informatice","i":[{"k":"S1.4-C5-R3-I1","t":"Gestionarea acesului la sistemul informatic este reglementata"},{"k":"S1.4-C5-R3-I2","t":"Aplicatiile informatice care acceseaza date cu caracter personal au setata secventa de delogare automata a utilizatorilor care nu utilizeaza aplicatia de un anumit timp"}]},{"n":"Inregistrarile permit identificarea autorului si a momentului efectuarii lor","i":[{"k":"S1.4-C5-R4-I1","t":"Aplicatiile informatice au implemetat un sistem de auditare al inregistrarilor prin stocarea informatiilor cu privire la utilizatorul si momentul in care a fost efectuata o operatiune in baza de date"}]},{"n":"Arhivarea documentelor, informatiilor si inregistrarilor este reglementata","i":[{"k":"S1.4-C5-R5-I1","t":"Exista un nomenclator arhivistic care prevede termenul de pastrare"},{"k":"S1.4-C5-R5-I2","t":"Documentele sunt amprentate cu termenul de pastrare"},{"k":"S1.4-C5-R5-I3","t":"Procedura de arhivare a documentelor implementata"}]},{"n":"Conditiile de pastrare a documentelor si arhivelor electronice repecta normele legale","i":[{"k":"S1.4-C5-R6-I1","t":"Sistem de evidență fizic și/sau electronic a documentelor arhivate, existent"},{"k":"S1.4-C5-R6-I2","t":"Distrugerea sau degradarea documentelor arhivate prevenite prin condițiile de păstrare."},{"k":"S1.4-C5-R6-I3","t":"Modalitatea de arhivare permite o accesare facilă a documentelor (ex: an/alfabetic/secţie)."},{"k":"S1.4-C5-R6-I4","t":"Condiţii de securitate pentru arhivarea fizică a FO împotriva distrugerii accidentale sau ilegale, pierderii, modificării, dezvăluirii sau accesului neautorizat precum şi împotriva oricărei alte forme de prelucrare ilegală, asigurate."}]},{"n":"Metodele de distrugere a inregistrarilor sunt proiectate in asa fel incat sa nu compromita confidentialitatea si securitatea datelor","i":[{"k":"S1.4-C5-R7-I1","t":"Propunerile de casare cuprind un desfasurator al documentelor propuse la casare si sunt aprobate de conducerea unitatii"},{"k":"S1.4-C5-R7-I2","t":"Exista certificate de predare, transport si distrugere pentru fiecare episod de casare a documentelor ce contin date cu caracter personal in ultimii 3 ani"}]}]},{"n":"Informatia poate fi furnizata in timp util, in formate utilizabil de catre beneficiar","e":[{"n":"Datele si informatiile furnizate corespund cerintelor beneficiarilor","i":[{"k":"S1.4-C6-R1-I1","t":"Diseminarea informatiilor este procedurata si exista anexate formatele de rapoarte uzuale, este specificata frecventa acestora, metodologia de completare pentru fiecare sector de activitate"},{"k":"S1.4-C6-R1-I2","t":"Exista un inventar al rapoartelor emise in spital corelat cu solicitarile interne si/sau externe"},{"k":"S1.4-C6-R1-I3","t":"Personalul medical are acces la baza de date in toate locatiile unde desfasoara activitate medicala"},{"k":"S1.4-C6-R1-I4","t":"Managementul are acces in timp real la datele si infomatiile necesare indeplinirii responsabilitatilor"},{"k":"S1.4-C6-R1-I5","t":"Pentru fiecare informatie poate fi identificat momentul solicitarii si momentul emiterii raspunsului"}]}]},{"n":"Sistemul informational este monitorizat si evaluat constant","e":[{"n":"Utilizatorii sistemului informational sunt pregatiti si au instruirea necesara pentru a utiliza informatiile","i":[{"k":"S1.4-C7-R1-I1","t":"Repetitivitatea actiunilor de audit intern din ultimii 3 (trei) ani cu tematica pe sistemul informational poate fi documentata"},{"k":"S1.4-C7-R1-I2","t":"Planul de formare profesionala cuprinde sesiuni de instruire dedicate Structurii de Securitate a Sistemului Informational si de Comunicatii cu tematica legislativa aplicabila domeniului"},{"k":"S1.4-C7-R1-I3","t":"Planul de formare este coroborat cu nevoile de date si informatii individuale si ale postului pentru fiecare categorie profesionala"},{"k":"S1.4-C7-R1-I4","t":"Instruirea personalului pentru utilizarea bazelor de date, efectuată conform planificării"},{"k":"S1.4-C7-R1-I5","t":"Responsabilii cu asigurarea Securitatii Sistemului Informational si de Comunicatii au fost instruiti pentru gestionarea si managementul informatiilor"}]},{"n":"Masurile pentru ameliorare riscurilor/deficientelor/disfunctionalitatilor au la baza rezultatele evaluarii","i":[{"k":"S1.4-C7-R2-I1","t":"Exista raport lunar privind evenimentele aparute in sistemul informational"},{"k":"S1.4-C7-R2-I2","t":"Exista evidente lunare pentru interventii si dezvoltare aplicatiile informatice"},{"k":"S1.4-C7-R2-I3","t":"Riscurile aferente sistemului informatic in raport cu fiabilitatea, complexitatea si scalabilitatea acestuia sunt identificate si au stabilite masuri corective"},{"k":"S1.4-C7-R2-I4","t":"Registrul riscurilor pentru sistemul informational a fost actualizat cel putin o data in ultimii 2 ani in raport cu disfunctionalitatile si deficientele semnalate"}]}]},{"n":"Instituţia are ca prioritate o politică integrată de gestionare a datelor pacientului","e":[{"n":"Gestiune corecta a datelor pacientului permite adaptarea constanta a ingrijirilor pacientului la nevoile acestora","i":[{"k":"S1.4-C8-R1-I1","t":"Procedură pentru consemnarea în toate documentele medicale (FO, FSZ, Bilet externare, Scrisoare medicală, Bilet transfer, DES) a incidentelor apărute în cursul spitalizării, cauzate tratamentului, investigațiilor (reacții alergice, reacții adverse, lipsă răspuns tratament, efecte secundare etc.) sau altor factori, implementată."},{"k":"S1.4-C8-R1-I2","t":"evoluția clinică consemnată zilnic în FO"},{"k":"S1.4-C8-R1-I3","t":"solicitarea pentru consultul de altă specialitate, consemnată în FO."},{"k":"S1.4-C8-R1-I4","t":"rezultatele investigaţiilor paraclinice, atașate FO"},{"k":"S1.4-C8-R1-I5","t":"transferul către o altă unitate medicală, motivat în FO."},{"k":"S1.4-C8-R1-I6","t":"îngrijirile și administrarea tratamentului/tratamentelor consemnate zilnic în zona dedicată a FO/fișa de tratament-terapie parte a FO"},{"k":"S1.4-C8-R1-I7","t":"prelucrarea datelor medicale din documentele medicale (FO/FSZ etc.) în scopul îmbunătățirii activității medicale, efectuată constant."},{"k":"S1.4-C8-R1-I8","t":"număr de FO cu (1)data și ora internării, (2)tipul internării, (3)criteriul de internare, (4)diagnosticul de trimitere, (5)diagnosticul de internare, (6)motivul/motivele internării si (7)alergii (dacă se cunosc) completate per număr total de FO selectate pentru evaluare"},{"k":"S1.4-C8-R1-I9","t":"număr de FO cu (1)diagnosticul la 72 ore, (2)istoricul bolii, (3)anamneza, (4)examenul clinic general și pe aparate, (5)examenul local si dupa caz, (6)alte examene de specialitate, investigatii, tratament efectuat la internare, (7)regimul de alimentație, de hidratare, (8)consimțământ informat și în funcție de situație, (9)diagnostic de externare (la cerere), diagnostic de transfer, diagnostic în caz de deces, epicriză completate per număr total de FO selectate pentru evaluare"},{"k":"S1.4-C8-R1-I10","t":"număr de FO cu (1)semnătura și parafa medicului curant, (2)evoluția și medicația înscrisă zilnic sau periodic, în funcție de patologie, (3)recomandările de tratament/terapii, (4)rezultatul investigațiilor imagistice, radiologice și de laborator (5)diagnosticul principal la externare, (6)diagnosticele secundare, (7)epicriza completată, (8)scrisoare medicală pentru medic familie, (9)prescripția electronică (printată)și dacă e cazul, (10)recomandare pentru îngrijiri la domiciliu, (11)recomandare pentru dispozitive medicale, (12)concediu medical completate per număr total de FO selectate pentru evaluare"},{"k":"S1.4-C8-R1-I11","t":"număr de FO cu (1)diagnosticul de transfer in secția de Terapie Intensivă, (2)evoluția zilnică a pacientului sau ori de câte ori este nevoie, (3)parametrii de monitorizat, (4)medicația de administrat, (5)hidratarea, (6)alimentația orală/parenterale, (7)manevrele antiescară etc. completate per număr total de FO selectate pentru evaluare"},{"k":"S1.4-C8-R1-I12","t":"recomandările medicului de gardă în cazul neinternării, consemnate în registrul de consultații"},{"k":"S1.4-C8-R1-I13","t":"comunicarea intre profesionisti se face asigurand acuratetea si protectia tututror informatiilor medicale"},{"k":"S1.4-C8-R1-I14","t":"Pacientul are accesul garantat la dosarul propriu, fie direct, fie prin intermediul unei persoane desemnate drepturilor sale"},{"k":"S1.4-C8-R1-I15","t":"accesul pacientului la datele medicale respectat conform drepturilor sale"},{"k":"S1.4-C8-R1-I16","t":"procedură privind eliberarea, la cerere, a copiei FO, respectând drepturile pacientului, implementată."},{"k":"S1.4-C8-R1-I17","t":"atribuţii specifice referitoare la gestiunea dosarului pacientului, existente în ROF"}]}]},{"n":"Gestionarea datelor pacientului este evaluată şi îmbunătățită continuu","e":[{"n":"Trimestrial sunt verificate mostre de documente de la pacientii internati si externati","i":[{"k":"S1.4-C9-R1-I1","t":"Planificarea verificării periodice a corectitudii completării FO, este respectată."},{"k":"S1.4-C9-R1-I2","t":"Verificarea este facuta de medici, asistente si alte persoane atorizate sa introduca si sa managerieze date;"},{"k":"S1.4-C9-R1-I3","t":"Procedura de verificare a FO cuprinde metoda de verificare pentru fiecare categorie de responsabili si este axata pe cronologie, lizibilitate si completarea datelor pacientilor"},{"k":"S1.4-C9-R1-I4","t":"Rapoartele de verificare a FO cuprind observatii defalcate pentru medici, asistenti, etc."}]},{"n":"Continutul inregistrarilor acopera legislatia si sunt incluse intr-un proces de revizuire","i":[{"k":"S1.4-C9-R2-I1","t":"Mecanismul de evaluare al procedurilor de colectare si gestiune a datelor prevad modul de revizuire, comunicare si implementare a modificarilor impuse prin schimbarile legislative"},{"k":"S1.4-C9-R2-I2","t":"Recomandări emise cu privire la completatrea corectă a FOCG în ultimul an"},{"k":"S1.4-C9-R2-I3","t":"Raportul asupra verificarii inregistrarilor medicale sunt preluate in mecanismul general de imbunatatire a calitatii."}]}]}]},{"c":"1.5","d":"1","n":"Sistemul de comunicare existent la nivelul spitalului raspunde nevoilor organizatiei si ale beneficiarilor","r":[{"n":"Spitalul are un cadru pentru comunicarea externă corespunzător cu nevoile sale.","e":[{"n":"Spitalul pune la dispoziția publicului canale de comunicare variate","i":[{"k":"S1.5-C1-R1-I1","t":"Pagină de internet proprie"},{"k":"S1.5-C1-R1-I2","t":"Număr de telefon pentru programări"},{"k":"S1.5-C1-R1-I3","t":"Adresa funcțională de mail a spitalului"},{"k":"S1.5-C1-R1-I4","t":"Informații complete privind modalitățile de acces la spital"},{"k":"S1.5-C1-R1-I5","t":"Alternative lingvistice la pagina de internet"},{"k":"S1.5-C1-R1-I6","t":"Pliant de prezentare"}]},{"n":"Spitalul creează pacientului condițiile pentru orientarea cu ușurință și identificarea interlocutorului","i":[{"k":"S1.5-C1-R2-I1","t":"Camera de internări/CPU/UPU este semnalizată distinct"},{"k":"S1.5-C1-R2-I2","t":"Elemente de identificare a personalului medical și administrativ - ecuson cu nume, titlu, funcție, departament"},{"k":"S1.5-C1-R2-I3","t":"Indicatoare de orientare către pavilioane, secții, cabinete"},{"k":"S1.5-C1-R2-I4","t":"Harta instituției"}]},{"n":"Spitalul oferă informații complete privind activitatea medicală prestată","i":[{"k":"S1.5-C1-R3-I1","t":"Informații privind condițiile de acces pentru aparținători - orar vizită"},{"k":"S1.5-C1-R3-I2","t":"Prezentarea serviciilor medicale și a echipei de profesioniști"},{"k":"S1.5-C1-R3-I3","t":"Serviciile oferite contra cost și condițiile pentru plată"},{"k":"S1.5-C1-R3-I4","t":"Tarifele serviciilor medicale"},{"k":"S1.5-C1-R3-I5","t":"Condițiile de internare"},{"k":"S1.5-C1-R3-I6","t":"Birou de informare/recepție"},{"k":"S1.5-C1-R3-I7","t":"Informații privind condițiile de externare"},{"k":"S1.5-C1-R3-I8","t":"Informaţii referitoare la dotările ale spitalului"}]},{"n":"Spitalul asigură comunicare corespunzătoare pentru continuitatea procesului de îngrijire","i":[{"k":"S1.5-C1-R4-I1","t":"Comunicare cu medicul de familie/medicul din ambulatoriu"},{"k":"S1.5-C1-R4-I2","t":"Informații privind asociații pentru îngrijiri și asistență postspitalizare"},{"k":"S1.5-C1-R4-I3","t":"Datele de contact a pacienților programabili, din listele de așteptare"},{"k":"S1.5-C1-R4-I4","t":"Informaţii referitoare la programe de sănătate în care instituţia este parte"},{"k":"S1.5-C1-R4-I5","t":"Recomandări privind controlul postexternare"},{"k":"S1.5-C1-R4-I6","t":"La externare pacientul primește bilet de externare, rezultatele investigaţiilor, costurile spitalizării, reţete, planul de îngrijiri medicale, după caz"}]},{"n":"Spitalul are organizată comunicarea cu mass-media","i":[{"k":"S1.5-C1-R5-I1","t":"Spitalul are purtător de cuvânt desemnat"},{"k":"S1.5-C1-R5-I2","t":"Accesul reprezentanților mass media în spital este procedurat și public"},{"k":"S1.5-C1-R5-I3","t":"Spitalul sau reprezentanții săi participă la acțiuni mass-media, de educație medicală sau sanitară."}]},{"n":"Spitalul are organizată comunicarea cu alte unități sanitare și alte structuri administrative","i":[{"k":"S1.5-C1-R6-I1","t":"Protocoale de colaborare cu instituții medicale"},{"k":"S1.5-C1-R6-I2","t":"Protocoale de colaborare cu alți furnizori de servicii medicale"},{"k":"S1.5-C1-R6-I3","t":"Protocoale de colaborare cu alte organizații."}]}]},{"n":"Spitalul are organizat un sistem de comunicare internă structurat și dimensionat corespunzător cu activitatea desfășurată","e":[{"n":"Regulile interne sunt comunicate personalului și pacienților.","i":[{"k":"S1.5-C2-R1-I1","t":"Reguli scrise de utilizare a lifturilor"},{"k":"S1.5-C2-R1-I2","t":"Regulile pe care pacientul, aparținătorii și vizitatorii trebuie să le respecte pe durata spitalizării sunt disponibile."},{"k":"S1.5-C2-R1-I3","t":"Afișarea programului de vizite, contravizite și gărzi"},{"k":"S1.5-C2-R1-I4","t":"Drepturile şi obligaţiile pacientului pe timpul spitalizării sunt comunicate"},{"k":"S1.5-C2-R1-I5","t":"Este înregistrat consimţământul semnat privind respectarea regulilor spitalului"},{"k":"S1.5-C2-R1-I6","t":"Consultul interdisciplinar în interiorul spitalului, reglementat în privința modului de solicitare și desfășurare"},{"k":"S1.5-C2-R1-I7","t":"Cod de culori pe categorii profesionale și sectoare critice"},{"k":"S1.5-C2-R1-I8","t":"Există o procedură care reglementează un sistem de comunicare de urgență între compartimentele spitalului"},{"k":"S1.5-C2-R1-I9","t":"Comunicarea deciziilor emise de Colegiul Medicilor și OAMR"},{"k":"S1.5-C2-R1-I10","t":"Există o procedură la nivelul spitalului care reglementează comunicarea între compartimentele administrative, paraclinice și clinice."}]},{"n":"Spitalul este pregătit să primească feedback privind activitatea pe care o desfășoară și valorizează informațiile primite astfel pentru îmbunătățirea activității","i":[{"k":"S1.5-C2-R2-I1","t":"Intervenții pentru îmbunătăţire serviciilor medicale și hoteliere luate în ultimul an calendaristic, ca urmare a prelucrării chestionarelor de evaluare a satisfacției pacienților și personalului"},{"k":"S1.5-C2-R2-I2","t":"Intervenții privind serviciile furnizate consecutiv unor reclamații"},{"k":"S1.5-C2-R2-I3","t":"Cutii de colectare a reclamaţiilor, plângerilor şi sesizărilor, existente şi accesibile pacienţilor şi vizitatorilor"},{"k":"S1.5-C2-R2-I4","t":"Evidență a reclamaţiilor sau plângerilor este monitorizată pe sectoare de activitate sau servicii furnizate"},{"k":"S1.5-C2-R2-I5","t":"Există un responsabil cu colectarea periodică a reclamaţiilor şi plângerilor - pentru întreg spitalul sau fiecare secţie"},{"k":"S1.5-C2-R2-I6","t":"Evidenţa hotărârilor şi avizelor de etică"}]}]},{"n":"Comunicarea între membrii echipei medicale are ca obiectiv permanent asistența medicală orientată către pacient","e":[{"n":"Instituția reglementează specific parametrii comunicării în zonele de activitate cu risc crescut","i":[{"k":"S1.5-C3-R1-I1","t":"Consult interclinic, completat în foaia de observație și semnat de medicul specialist"},{"k":"S1.5-C3-R1-I2","t":"Medicaţia recomandată de alți specialiști este consemnată și semnată."},{"k":"S1.5-C3-R1-I3","t":"Fișa de anestezie completată este accesibilă tutror membrilor echipei de îngrijiri"},{"k":"S1.5-C3-R1-I4","t":"Există o procedură la nivelul spitalului pentru transmiterea cu prioritate a rezultatelor analizelor, investigațiilor sau a oricărei situații amenințătoare pentru viață."}]},{"n":"Instituția reglementează specific parametrii comunicării medicale","i":[{"k":"S1.5-C3-R2-I1","t":"Existenţa sau absenţa alergiilor medicamentoase şi contraindicaţiilor medicamentoase, consemnate în FOCG/ fișa de anestezie sau alt formular special"},{"k":"S1.5-C3-R2-I2","t":"FOCG însoțește întotdeauna pacientul și este accesată numai de personalul medical"},{"k":"S1.5-C3-R2-I3","t":"Evoluţia stării de sănătate a pacientului, consemnată zilnic sau ori de câte ori este necesar în FOCG /FSZ"},{"k":"S1.5-C3-R2-I4","t":"Parametrii generali ai evoluției clinice - temperatură, diureză, frecvența respirației, frecvența cardiacă și tensiunea arterială sunt consemnați zilnic în FOCG"},{"k":"S1.5-C3-R2-I5","t":"Investigațiile radiologice, analizele de laborator și tratamentele efectuate sunt consemnate în fișele pentru spitalizare de zi"},{"k":"S1.5-C3-R2-I6","t":"Numărul FOCG cu toate diagnosticele completate - la internare, la 72 de ore şi la externare/ nr. total de FOCG selectate"}]},{"n":"Spitalul are o evidență clară a interacțiunilor cu pacientul și a problemelor specifice fiecărui caz.","i":[{"k":"S1.5-C3-R3-I1","t":"Data și ora internării consemnate în FOCG și registrul de internări"},{"k":"S1.5-C3-R3-I2","t":"În cazul neinternării, medicul de gardă consemnează în registrul de consultații refuzul și recomandările"},{"k":"S1.5-C3-R3-I3","t":"Lipsa discernământului documentată în FOCG și registrul de consultații"}]},{"n":"Colaborarea interdisciplinară este o practică curentă.","i":[{"k":"S1.5-C3-R4-I1","t":"Proceduri privind constituirea comisiei de arbitraj privind oportunitatea unei intervenții medicale (pentru pacienții aflați în incapacitatea de a-și da consimțământul)"},{"k":"S1.5-C3-R4-I2","t":"La rapoartele de gardă participă toți specialiștii care pot contribui la la creșterea calității actului medical prin aportul de informații specifice."},{"k":"S1.5-C3-R4-I3","t":"Spitalul organizează sesiuni de comunicări medicale, prezentări de caz sau experiențe profesionale"}]},{"n":"Spitalul este preocupat de calitatea informațiilor medicale transmise între membrii echipei medicale care participă la îngrijirea pacientului, cât și între aceștia și specialiști externi.","i":[{"k":"S1.5-C3-R5-I1","t":"Setul minim de informații medicale de transmis la predarea/primirea pacientului"},{"k":"S1.5-C3-R5-I2","t":"Protocol de transfer al pacientului interclinic sau la alte unități de îngrijire"},{"k":"S1.5-C3-R5-I3","t":"Setul minim de informații de transmis telefonic în solicitarea de transfer a pacientului."}]},{"n":"Spitalul folosește sisteme standardizate de codificare a bolilor, coduri pentru proceduri, simboluri, abrevieri și definiții standardizate.","i":[{"k":"S1.5-C3-R6-I1","t":"Sunt folosite coduri de diagnostic standardizate și respectarea codificării este monitorizată."},{"k":"S1.5-C3-R6-I2","t":"Sunt folosite coduri de procedură standardizate și respectarea codificării este monitorizată."},{"k":"S1.5-C3-R6-I3","t":"Sunt folosite definiții clare și unanim acceptate/standardizate"},{"k":"S1.5-C3-R6-I4","t":"Sunt folosite simboluri cunoscute și unanim acceptate/standard și cele care nu trebuie utilizate sunt monitorizate și identificate."},{"k":"S1.5-C3-R6-I5","t":"Sunt folosite abrevieri unanim acceptate/standard și cele care nu trebuie utilizate sunt monitorizate și identificate"}]}]},{"n":"Comunicarea cu pacientul îi permite acestuia participarea la procesul de îngrijiri","e":[{"n":"Pacientului și aparținătorii sunt tratați ca parteneri în actul medical.","i":[{"k":"S1.5-C4-R1-I1","t":"Spitalul are o politică activă de implicare a pacienților și aparținătorilor în planificarea și implementarea tratamentului în situațiile care impun."},{"k":"S1.5-C4-R1-I2","t":"Spitalul planifică și tratează pacientul în acord cu politica proprie de implicare a pacientului în decizii"},{"k":"S1.5-C4-R1-I3","t":"Spitalul stabilește ținte de calitate pentru implicarea pacientului sau aparținătorilor în procesul de îngrijiri."},{"k":"S1.5-C4-R1-I4","t":"Spitalul evaluează obiectivele de calitate propuse pacienților și aparținătorilor măcar o dată pe an"},{"k":"S1.5-C4-R1-I5","t":"Spitalul implementează măsuri pentru a crește calitatea implicării ca parteneri a pacienților și aparținătorilor."},{"k":"S1.5-C4-R1-I6","t":"Spitalul evaluează periodic și aplică corecțiile necesare pentru îmbunătățirea acestor măsuri."}]},{"n":"Comunicarea este adaptată la nevoile fiziologice, culturale și religioase a pacientului","i":[{"k":"S1.5-C4-R2-I1","t":"Sunt identificate și consemnat modalități de comunicare specifică pentru pacienții cu deficiențe"},{"k":"S1.5-C4-R2-I2","t":"Stabilirea necesarului de comunicare a pacientului în situațiile de transferului"},{"k":"S1.5-C4-R2-I3","t":"Monitorizarea statusului de comunicare a pacientului terminal"},{"k":"S1.5-C4-R2-I4","t":"Sunt identificate modalități de comunicare adaptate nevoile culturale și religioase a pacientului"},{"k":"S1.5-C4-R2-I5","t":"Spitalul are o ofertă meniuri adaptate convingerilor religioase a pacientului"},{"k":"S1.5-C4-R2-I6","t":"Spitalul oferă suport spiritual pacienților pe durata internării"}]},{"n":"Informațiile importante sunt transmise într-o manieră profesională","i":[{"k":"S1.5-C4-R3-I1","t":"Spitalul definește care sunt categoriile de informațiile considerate necesare a fi comunicate în situații speciale."},{"k":"S1.5-C4-R3-I2","t":"Există un ghid pentru personalul medical pentru gestionarea conversațiilor importante"},{"k":"S1.5-C4-R3-I3","t":"Conversațiile importante se desfășoară într-un cadru care să asigure confidențialitatea și să evite alți factori perturbatori."},{"k":"S1.5-C4-R3-I4","t":"Personalul medical care poartă conversația se asigură că este prezent, dacă este nevoie, și un interpret."},{"k":"S1.5-C4-R3-I5","t":"Personalul medical care poartă conversația se asigură că este prezent un reprezentant legal pentru situațiile care impun acest lucru."},{"k":"S1.5-C4-R3-I6","t":"Spitalul implementează măsuri pentru a crește calitatea conversațiilor importante"},{"k":"S1.5-C4-R3-I7","t":"Spitalul evaluează periodic și aplică corecțiile necesare pentru îmbunătățirea acestor măsuri."},{"k":"S1.5-C4-R3-I8","t":"Spitalul utilizează un sistem de comunicare specific pentru informațiile medicale critice."}]},{"n":"Spitalul definește informațiile importante care vor fi transmise în formă scrisă pacientului.","i":[{"k":"S1.5-C4-R4-I1","t":"Spitalul definește informațiile care trebuie comunicate pacientului în scris."},{"k":"S1.5-C4-R4-I2","t":"Nr. pacienţi care afirmă că au fost informaţi verbal în privința drepturilor lor de către medic/asistentă/nr. pacienţi chestionaţi"},{"k":"S1.5-C4-R4-I3","t":"Nr. pacienţi care au fost informaţi în privinţa drepturilor lor printr-un tipizat atașat FOCG/nr. pacienţi chestionaţi"}]}]},{"n":"Educația pentru sănătate a pacientului este o preocupare pentru întreaga instituție medicală","e":[{"n":"Spitalul are implementat un sistem de evaluare a necesarului individual de instruire a pacientului și există o structură care să furnizeze instruirea necesară.","i":[{"k":"S1.5-C5-R1-I1","t":"Nevoile de educație a pacientului și familiei sunt evaluate și înregistrate în FO"},{"k":"S1.5-C5-R1-I2","t":"Capacitatea și dorința de a învăța, a pacientului și aparținătorilor sunt evaluate și consemnate"},{"k":"S1.5-C5-R1-I3","t":"Metodele de educare includ preferințele și valorile pacientului și familiei și sunt suficiente pentru a a asigura învățarea"},{"k":"S1.5-C5-R1-I4","t":"Profesioniștii din sănătate colaborează pentru a furniza educație"},{"k":"S1.5-C5-R1-I5","t":"Spitalul are în derulare un program de instruire a personalului privind cunoaşterea şi respectarea drepturilor pacientului"}]},{"n":"Spitalul are implementat un sistem de educare continuuă a personalului privind comunicarea cu pacientul și programe specifice de educație terapeutică.","i":[{"k":"S1.5-C5-R2-I1","t":"Spitalul desfășoară programe de educație terapeutică"},{"k":"S1.5-C5-R2-I2","t":"Spitalul are în derulare un program de instruire a personalului privind comunicarea cu categoriile specifice de pacienți - copii, vârstnici, cu deficiențe senzoriale."},{"k":"S1.5-C5-R2-I3","t":"Spitalul își planifică programul educațional orientat spre pacient corelat cu misiunea sa și nevoile populației pe care o deservește"}]}]}]},{"c":"1.6","d":"1","n":"Sistemul de management al calitatii vizeaza optimizarea continua a proceselor de la nivelul organizatiei.","r":[{"n":"Conducerea spitalului sprijina dezvoltarea culturii privind calitatea serviciilor medicale si siguranta pacientului","e":[{"n":"Imbunatatirea culturii se face prin activitati specifice","i":[{"k":"S1.6-C1-R1-I1","t":"Program de instruire si educare a personalului"},{"k":"S1.6-C1-R1-I2","t":"Cod de conduita a personalului"},{"k":"S1.6-C1-R1-I3","t":"Incurajarea raportarii evenimentelor adverse"}]}]},{"n":"Spitalul planifica si implementeaza un program de management al calitatii serviciilor si sigurantei pacientilor","e":[{"n":"Structura de management al calitatii este reprezentata/este condusa de catre o persoana cu experienta si calificari in domeniul calitatii","i":[{"k":"S1.6-C2-R1-I1","t":"dovada participarii la instruiri privind calitatea si imbunatatirea proceselor"}]},{"n":"Elaborarea programului de management al calitatii se bazeaza pe analiza informatiilor privind calitatea serviciilor si siguranta pacientilor","i":[{"k":"S1.6-C2-R2-I1","t":"Analiza calitatii serviciilor pe ultimul an calendaristic incheiat"},{"k":"S1.6-C2-R2-I2","t":"Lista problemelor identificate"}]},{"n":"UMCS coordoneaza elaborarea programului de management al calitatii","i":[{"k":"S1.6-C2-R3-I1","t":"I1. Propuneri ale sefilor sectoarelor de activitate privind imbunatatirea calitatii serviciilor"},{"k":"S1.6-C2-R3-I2","t":"I2. Prioritizarea ariilor de imbunatatit"},{"k":"S1.6-C2-R3-I3","t":"I3.Programul contine obiective si indicatori generali pentru spital si specifici pentru fiecare sectie"}]},{"n":"Programul de management al calitatii si sigurantei pacientilor este asumat de catre conducerea unitatii","i":[{"k":"S1.6-C2-R4-I1","t":"Decizia de aprobare a programului"},{"k":"S1.6-C2-R4-I2","t":"difuzarea planului in institutie si instruirea personalului"}]},{"n":"Programul de management al calitatii cuprinde actiuni specifice privind siguranta pacientilor","i":[{"k":"S1.6-C2-R5-I1","t":"Prevederi privind implementarea standardelor de siguranta a pacientului"},{"k":"S1.6-C2-R5-I2","t":"prevederi privind elaborarea de protocoale de ingrijire sau adoptarea de ghiduri clinice"},{"k":"S1.6-C2-R5-I3","t":"incurajarea personalului pentru a participa la revizuirea protocoalelor/ ghidurilor"},{"k":"S1.6-C2-R5-I4","t":"activitatile sunt monitorizate prin indicatori specifici"}]},{"n":"UMCS monitorizeaza implementarea programului de management al calitatii","i":[{"k":"S1.6-C2-R6-I1","t":"Lista a indicatorilor de monitorizare"},{"k":"S1.6-C2-R6-I2","t":"I2. Plan de audit pentru monitorizarea imbunatatirilor"}]},{"n":"Spitalul imbunatateste permanent serviciile pe baza programului de management al calitatii","i":[{"k":"S1.6-C2-R7-I1","t":"Recomandari scrise privind rezultatele analizei indicatorilor"},{"k":"S1.6-C2-R7-I2","t":"Masurile adoptate spre implementare"}]}]},{"n":"Spitalul dezvolta un program de management al riscurilor","e":[{"n":"Spitalul analizeaza anual riscurile generate de activitatile desfasurate","i":[{"k":"S1.6-C3-R1-I1","t":"Registrul riscurilor"},{"k":"S1.6-C3-R1-I2","t":"Masuri de diminuare a riscurilor majore"}]},{"n":"Spitalul are elaborata si aplica o procedura de gestionare a evenimentelor santinela","i":[{"k":"S1.6-C3-R2-I1","t":"Procedura de gestionare formalizata"},{"k":"S1.6-C3-R2-I2","t":"Structura procedurii"}]},{"n":"Spitalul a elaborat si aplica o procedura de gestionare a evenimentelor cu potential grav (near miss)","i":[{"k":"S1.6-C3-R3-I1","t":"Procedura de gestionare formalizata"},{"k":"S1.6-C3-R3-I2","t":"Structura procedurii"}]},{"n":"Spitalul a dezvoltat un sistem de raportare a evenimentelor adverse (evenimente santinela sau cu potential grav (near miss))","i":[{"k":"S1.6-C3-R4-I1","t":"Set minim de date care permit analiza evenimentului"},{"k":"S1.6-C3-R4-I2","t":"Instructiuni de completare a sistemului de raportare"},{"k":"S1.6-C3-R4-I3","t":"Instruirea personalului pentru raportare"}]},{"n":"Raportarile privind evenimentele adverse sunt analizate de catre RMCS","i":[{"k":"S1.6-C3-R5-I1","t":"Probleme identificate si masuri propuse"},{"k":"S1.6-C3-R5-I2","t":"Masuri adoptate de catre conducere si comunicate personalului"}]}]},{"n":"Spitalul urmareste cresterea nivelului de satisfactie a pacientilor","e":[{"n":"Spitalul elaboreaza si actualizeaza periodic chestionare de satisfactie a pacientilor","i":[{"k":"S1.6-C4-R1-I1","t":"Chestionar de satisfactie a pacientului"},{"k":"S1.6-C4-R1-I2","t":"Cel putin o revizie anuala a chestionarului"},{"k":"S1.6-C4-R1-I3","t":"continutul chestionarului permite pastrarea anonimatului sau identificarea pacientului cand acesta doreste"}]},{"n":"Spitalul a elaborat si aplica o procedura de gestionare a reclamatiilor","i":[{"k":"S1.6-C4-R2-I1","t":"Procedura formalizata"},{"k":"S1.6-C4-R2-I2","t":"Procedura implementata"}]},{"n":"UMCS analizeaza sistematic informatiile rezultate din prelucrarea chestionarelor si gestionarea reclamatiilor si emite periodic recomandari","i":[{"k":"S1.6-C4-R3-I1","t":"Baza de date culese din chestionare"},{"k":"S1.6-C4-R3-I2","t":"Evidenta reclamatiilor"}]},{"n":"Spitalul utilizeaza analiza periodica a reclmatiilor primite pentru a imbunatati serviciile medicale furnizate","i":[{"k":"S1.6-C4-R4-I1","t":"analiza periodica a reclamatiilor"},{"k":"S1.6-C4-R4-I2","t":"recomandari de imbunatatireale UMCS dupa ultima analiza a reclamatiilor"}]}]},{"n":"Programul de imbunatatire a calitatii prevede eficientizarea activitatii spitalului","e":[{"n":"Departamentele si sectiile spitalului au implementat minim un ghid clinic si minim un protocol specific de ingrijire a pacientilor","i":[{"k":"S1.6-C5-R1-I1","t":"dovada adoptarii minim a unui ghid clinic/fiecare sectie sau departament clinic"},{"k":"S1.6-C5-R1-I2","t":"dovada elaborarii de protocoale de ingrijire pentru pacienti"},{"k":"S1.6-C5-R1-I3","t":"complaterea si revizuirea zilnica de personalul medical, in functie de evolutia pacientului"},{"k":"S1.6-C5-R1-I4","t":"protocol intern pentru managementul urgentelor medicale"},{"k":"S1.6-C5-R1-I5","t":"instruirea personalului a fost instruit si implementarea (dovada- semnaturi de luare la cunostinta protocol sau curs intern)"},{"k":"S1.6-C5-R1-I6","t":"simulari interne"}]},{"n":"Ambulatoriul spitalului participa la eficientizarea activitatii spitalului","i":[{"k":"S1.6-C5-R2-I1","t":"I1. program de functionare a cabinetelor"},{"k":"S1.6-C5-R2-I2","t":"I2. Amenajarea spatiului ambulatoriului permite asteptarea in conditii bune (scaune, toalete aceesibile, distribuitoare de apa)"},{"k":"S1.6-C5-R2-I3","t":"I3. structuri functionale care asigura primirea pacientilor, triajul si internarea acestora in conditii optime"},{"k":"S1.6-C5-R2-I4","t":"Servicii medicale complementare furnizate in ambulator pentru asigurarea continuitatii ingrijirilor acordate pacientilor"}]}]}]},{"c":"1.7","d":"1","n":"Managementul riscului este o componentă a managementului organizaţional","r":[{"n":"Adoptarea de măsuri manageriale pentru asigurarea securității persoanelor în conformitate cu Conceptul adoptat de ANMCS","e":[{"n":"Măsurile de management prezente în planuri conduc la evitarea accidente lor și/sau evenimentelor nedorite evidențiate în normativul specific și la respectarea regulilor/normelor stabilite la nivel republican și local","i":[{"k":"S1.7-C1-R1-I1","t":"Staff-ul instituției a efectuat analizele de risc pe tipuri și probabilități/impact al producerii și a doptat măsuri dedicate"},{"k":"S1.7-C1-R1-I2","t":"Instruirea persoanelor conform celor legale; verificările structurilor/instituțiilor cu expertiză pe domeniu consemnează starea de legalitate"},{"k":"S1.7-C1-R1-I3","t":"Existența evidenței, individualizată pe categorii și stări a bunurilor care, prin cedare materială, pot produce sau pot contribui la răniri/afectări corporale sau ale mediului."},{"k":"S1.7-C1-R1-I4","t":"Utilizarea instrucțiunile de folosire a bunurilor/instrumentarelor/dispozitivelor etc."},{"k":"S1.7-C1-R1-I5","t":"Îmbunătățirea condițiilor de muncă"},{"k":"S1.7-C1-R1-I6","t":"Existența documentelor prevăzute de lege pentru stabilirea titlului asupra imobilelor"},{"k":"S1.7-C1-R1-I7","t":"Expertizarea tehnică pentru construcțiile/ instalațiile a căror situație o impune (expertizare și auditare, certificare energetică etc.); autorizarea/atestarea stării acestora"},{"k":"S1.7-C1-R1-I8","t":"Efectuarea conform normelor a întreținerilor și reparațiilor la construcții; Cartea tehnică a construcției/Jurnalul evenimentelor; Urmărirea specială a comportării construcțiilor"},{"k":"S1.7-C1-R1-I9","t":"Existența de avertizări legate de starea construcțiilor (dacă este cazul)"},{"k":"S1.7-C1-R1-I10","t":"Starea instalațiilor și Starea împrejmuirilor"},{"k":"S1.7-C1-R1-I11","t":"Starea și funcționalitatea geamurilor, ușilor, dimensionarea și poziționarea după utilizare și alte norme (PSI, Radiologie, Toxice) etc"},{"k":"S1.7-C1-R1-I12","t":"Alocarea per* persoane după norme (volum de aer, suprafață, WC, baie, chiuvete etc)"},{"k":"S1.7-C1-R1-I13","t":"Dotarea cu mobilier, echipamente, cazarmament"},{"k":"S1.7-C1-R1-I14","t":"Există documentele care reglementează paza și protecția obiectivului sanitar, iar serviciul adoptat funcționează"},{"k":"S1.7-C1-R1-I15","t":"Reglementarea accesului; asigurarea limitărilor și interdicțiilor; existența unui sistem de dirijare a fluxurilor de acces și evacuare; informarea publicului"},{"k":"S1.7-C1-R1-I16","t":"Echiparea, dotarea, instruirea, atestarea (dacă este cazul) personalului cu responsabilități de pază și protecție"},{"k":"S1.7-C1-R1-I17","t":"Dotarea cu mijloace de supraveghere"},{"k":"S1.7-C1-R1-I18","t":"Existența documentelor de autorizare/ atestare pe linia Protecției mediului"},{"k":"S1.7-C1-R1-I19","t":"Organizarea activității de protecție a mediului; plan de lucru; responsabilizări"},{"k":"S1.7-C1-R1-I20","t":"Înștiințarea, cooperarea, avertizarea"},{"k":"S1.7-C1-R1-I21","t":"Atestarea/autorizare privind activitatea de tip nuclear/radiologic în instituție"},{"k":"S1.7-C1-R1-I22","t":"Accesul autorizat la materiale și instalații"},{"k":"S1.7-C1-R1-I23","t":"Realizarea trasabilității în privința materialelor și tehnologiei specifice"},{"k":"S1.7-C1-R1-I24","t":"Utilizarea în siguranță a aparaturii de măsură și control a radiațiilor"},{"k":"S1.7-C1-R1-I25","t":"Asigurarea trasabilității substanțelor/compușilor periculoși sau cu regim restricționat, precursori sau cu utilizare duală etc."},{"k":"S1.7-C1-R1-I26","t":"Măsurile pentru evitarea confuziilor, greșelilor în LSPRR"},{"k":"S1.7-C1-R1-I27","t":"Asigurarea accesul controlat/ autorizat la substanțe și locuri de păstrare/depozitare"},{"k":"S1.7-C1-R1-I28","t":"Adoptarea de planuri și măsuri pentru Organizarea activității PSI"},{"k":"S1.7-C1-R1-I29","t":"Dobândirea documentelor specifice pentru locurile/instalațiile etc. care se supun autorizării/avizării d.p.d.v. P.S.I."},{"k":"S1.7-C1-R1-I30","t":"Realizarea pregătirii personalului pe linia PSI"},{"k":"S1.7-C1-R1-I31","t":"Stadiul dotări cu bunuri specifice, evidența și starea acestora"},{"k":"S1.7-C1-R1-I32","t":"Existența de Avertizări și marcaje specifice"},{"k":"S1.7-C1-R1-I33","t":"Organizarea activității proprii pentru prevenirea pandemiilor și epizootiilor"},{"k":"S1.7-C1-R1-I34","t":"Adoptarea de măsuri pentru organizarea activității cu terți pentru prevenirea pandemiilor și epizootiilor"},{"k":"S1.7-C1-R1-I35","t":"Adoptarea de măsuri structurale și organizatorice pe linia Pr. Civ."},{"k":"S1.7-C1-R1-I36","t":"Starea adăposturilor de protecție civilă (dacă este cazul)"},{"k":"S1.7-C1-R1-I37","t":"Stabilirea situațiilor ipotetice și a măsurilor/standardelor operaționale specifice."},{"k":"S1.7-C1-R1-I38","t":"Modul de Organizarea activității și instruirea personalului pentru MSC"},{"k":"S1.7-C1-R1-I39","t":"Cooperarea cu structuri/instituții de specialitate"},{"k":"S1.7-C1-R1-I40","t":"Atestarea Stării tehnice a autovehiculelor"},{"k":"S1.7-C1-R1-I41","t":"Corespondența atestării profesionale cu încadrarea conducătorilor auto"},{"k":"S1.7-C1-R1-I42","t":"Preocuparea și măsurile pentru Perfecționarea profesională a conducătorilor auto"},{"k":"S1.7-C1-R1-I43","t":"Există o Partajare a responsabilităților și asumarea acestora ca urmare a deciziilor, dispozițiilor, curinderii în atribuții, fișe ale postului, indicații comportamentale la locul de muncă etc."},{"k":"S1.7-C1-R1-I44","t":"Asigurarea ”memoriei” manageriale a domeniilor"},{"k":"S1.7-C1-R1-I45","t":"Preocuparea pentru rezolvarea problemelor deficitare, a neajunsurilor ori a recomandărilor organelor de control și îndrumare"},{"k":"S1.7-C1-R1-I46","t":"Analizarea și evaluarea propriei activități"},{"k":"S1.7-C1-R1-I47","t":"Recurgerea la norme legale în luarea deciziilor"},{"k":"S1.7-C1-R1-I48","t":"Relaționarea pe orizontală și pe verticală cu privire la riscurile non clinice asociate acordării actului medical"}]}]}]},{"c":"2.1","d":"2","n":"Managementul serviciilor medicale si de ingrijiri","r":[{"n":"Planul de îngrijire al pacientului este implementat","e":[{"n":"Planul de îngrijire individualizat este întocmit de către asistentul medical și adoptat împreună cu pacientul și sau familia sa/aparținătorii/reprezentantul legal.","i":[{"k":"S2.1-C1-R1-I1","t":"Activitatea de elaborare și implementare a planului de îngrijire este procedurată"},{"k":"S2.1-C1-R1-I2","t":"Responsabilități privind întocmirea și implementarea planului de îngrijire existente în fișele de post ale cadrelor medicale (medici, asistenți medicali, infirmiere)"},{"k":"S2.1-C1-R1-I3","t":"Planul de îngrijire are în vedere și satisfacerea nevoilor spirituale, religioase și culturale ale pacientului"},{"k":"S2.1-C1-R1-I4","t":"Externarea pacientului este programată și documentată"}]},{"n":"Implementarea planului de îngrijire se face de către asistentul medical împreună cu pacientul și sau familia sa/aparținătorii/reprezentantul legal și include recomandările medicale","i":[{"k":"S2.1-C1-R2-I1","t":"În planul de îngrijire se consemnează intervențiile proprii efectuate de către asistentul medical în limita competențelor proprii"},{"k":"S2.1-C1-R2-I2","t":"În planul de îngrijire se consemnează intervențiile efectuate de către asistentul medical la recomandarea echipei multidisciplinare implicată în îngrijirea pacientului (medic, fizioterapeut, asistent social, psiholog, infirmier, consilier spiritual etc)"},{"k":"S2.1-C1-R2-I3","t":"Protocol privind prevenirea, tratarea și monitorizarea complicațiilor legate de acordarea îngrijirilor, implementat"},{"k":"S2.1-C1-R2-I4","t":"Pacientul și/sau familia/aparținătorii/reprezentanții legali ai acestuia sunt implicați în implementarea planului de îngrijire"},{"k":"S2.1-C1-R2-I5","t":"Educația pentru sănătate a pacientului și sau familiei/aparținătorilor/reprezentantului legal este procedurată"},{"k":"S2.1-C1-R2-I6","t":"Colaborari cu preoţi sau îndrumători spirituali, existente în vederea asigurării spijinului confesional și moral (Da/Nu)"},{"k":"S2.1-C1-R2-I7","t":"Listă cu organizațiile de îngrijiri la domiciliu, medici de familie care au încheiat protocoale de colaborare cu spitalul accesibilă pacienților (Da/Nu)"}]},{"n":"Alocarea personalului de îngrijire se face în funcție de rezultatele aplicării unui instrument de evaluare a îngrijirilor","i":[{"k":"S2.1-C1-R3-I1","t":"Spitalul are adoptat un instrument de evaluare și cuntificare a îngrijirilor efectuate"},{"k":"S2.1-C1-R3-I2","t":"Alocarea numărului de pacienți în îngrijirea asistentului medical se face calculând numărul de ore necesare îngrijirii pacienților în funcție de instrumentul adoptat"}]},{"n":"Evaluarea planului de îngrijire se face periodic și la externare","i":[{"k":"S2.1-C1-R4-I1","t":"Evaluarea planului de îngrijire se face în funcție de fiecare obiectiv stabilit"},{"k":"S2.1-C1-R4-I2","t":"Reajustarea planului de îngrijire se face în funcție de evaluarile intermediare și finale ale Obiectivelor stabilite"},{"k":"S2.1-C1-R4-I3","t":"Nr. pacienţi care au dezvoltat complicații legate de îngrijire/nr. pacienţi internaţi în ultimul an calendaristic încheiat"},{"k":"S2.1-C1-R4-I4","t":"Analiza satisfacției pacientului în legătură cu planul de îngrijire"},{"k":"S2.1-C1-R4-I5","t":"Nr. cursuri de educație medicală continuă pe tema planului de îngrijire susținute de spital per asistent medical per sectie per ultimul an calendaristic"},{"k":"S2.1-C1-R4-I6","t":"Obiective punctuale de îmbunătăţire a calităţii serviciilor de îngrijire a pacientului prin implemnetarea planului de îngrijire - stipulate în atribuțiile medicului șef"},{"k":"S2.1-C1-R4-I7","t":"Studii de cercetare nursing derulate în spital în ultimii 5 ani"},{"k":"S2.1-C1-R4-I8","t":"Monitorizarea evoluției pacientului post internare – prin organizațiile de îngrijiri la domiciliu și medicul de familie este procedurată"}]}]}]},{"c":"2.2","d":"2","n":"Managementul farmaceutic și al medicației asigură continuitatea îngrijirilor și siguranța pacientului","r":[{"n":"Condițiile de urmărire a trasabilității medicamentului sunt cunoscute și urmărite","e":[{"n":"RESPONSABILITĂȚI SPECIFICE SPECIALIZĂRII ÎNSCRISE ÎN FIȘA POSTULUI","i":[{"k":"S2.2-C1-R1-I1","t":"dosare personale completate și actualizate"},{"k":"S2.2-C1-R1-I2","t":"realizarea EMC pentru farmaciști și asistenți de farmacie, urmărită"},{"k":"S2.2-C1-R1-I3","t":"grafice de lucru pentru fiecare angajat, cu evidența activității zilnice, realizate"},{"k":"S2.2-C1-R1-I4","t":"existența concordanței între competențele rezultate din înscrisuri și evaluarea anuală a activității conform Fișei Postului"},{"k":"S2.2-C1-R1-I5","t":"înregistrarea etapelor de activitate specifice se face sub semnătură în documentația farmaciei"},{"k":"S2.2-C1-R1-I6","t":"farmacistul clinician monitorizează schemele de tratament"}]},{"n":"DOCUMENTE NECESARE UNEI BUNE DESFĂȘURĂRI A ACTIVITĂȚII SPECIFICE LA NIVEL DE FARMACIE","i":[{"k":"S2.2-C1-R2-I1","t":"activitatea farmaciei desfășurată în baza Autorizației de funcționare emisă de MS pe numele farmacistului șef,cu specificarea tuturor punctelor de lucru autorizate"},{"k":"S2.2-C1-R2-I2","t":"lista validată, a furnizorilor autorizați selectați în urma procedurii de achiziție și a contractelor, accesibilă informatic la nivel de farmacie"},{"k":"S2.2-C1-R2-I3","t":"nomenclatorul de medicamente validat în vederea utilizării în spital (actualizat cel puțin odata pe an) și accesibil informatic personalului medical"},{"k":"S2.2-C1-R2-I4","t":"conformitatea stocului curent al farmaciei cu nomenclatorul"},{"k":"S2.2-C1-R2-I5","t":"medicamentele cu distribuție controlată sunt aprobate de șeful de secție/departament/serviciu"},{"k":"S2.2-C1-R2-I6","t":"există responsabili cu termenele de valabilitate și monitorizarea retragerii produselor farmaceutice care expiră, de pe secțiile medicale și din farmacie"},{"k":"S2.2-C1-R2-I7","t":"există contractele valabile, cu firme autorizate, pentru distrugerea medicamentelor expirate"}]},{"n":"ORGANIZAREA CORESPUNZĂTOARE A SPAȚIULUI DE LUCRU, DOTĂRI","i":[{"k":"S2.2-C1-R3-I1","t":"farmacia respectă structura cu circuitele prevăzute în autorizare"},{"k":"S2.2-C1-R3-I2","t":"farmacia respectă circuitele obligatorii și condițiile de păstrare ale produselor farmaceutice"}]},{"n":"RESPECTAREA CIRCUITULUI INFORMAȚIONAL AL PRODUSELOR FARMACEUTICE","i":[{"k":"S2.2-C1-R4-I1","t":"corespondența între elementele de identificare ale produselor și substanțelor farmaceutice înscrise în factura fiscală și cele ale produselor și substanțelor farmaceutice recepționate înscrise în NIR –ul aferent programului de gestiune"},{"k":"S2.2-C1-R4-I2","t":"registru de neconformități pentru recepția produselor farmaceutice, completat la zi"},{"k":"S2.2-C1-R4-I3","t":"programul de gestiune informatică permite, în orice moment al circuitului medicamentului în farmacie, verificarea veridicității și monitorizarea produselor farmaceutice"},{"k":"S2.2-C1-R4-I4","t":"registre pentru substanțe farmaceutice și pentru prepararea apei distilate, evidența preparatelor magistrale și produse elaborate, completat la zi"},{"k":"S2.2-C1-R4-I5","t":"se respectă corespondența între substanța existentă în recipientul farmaciei, numărul de înregistrare al lotului din registru de evidență substanțe famaceutice și înscrisul de pe ambalajul furnizorului"},{"k":"S2.2-C1-R4-I6","t":"seria/lotul substanțelor utilizate la prepararea magistralelor este înregistrată în registrul preparatelor magistrale și al produselor elaborate"},{"k":"S2.2-C1-R4-I7","t":"eticheta de identificare a preparatului magistral sau a celui elaborat conține numărul de înregistrare din registrele corespunzătoare, date de identificare ale persoanei care a preparat și a celei care a ambalat medicamentul magistral sau oficinal"},{"k":"S2.2-C1-R4-I8","t":"registre de evidență stupefiante și psihotrope, conform legislației specifice, completate la zi și securizate"},{"k":"S2.2-C1-R4-I9","t":"procedură de validarea prescripției prin identificarea corectă a pacientului,, a prescriptorului, a datei prescrierii, implementată"},{"k":"S2.2-C1-R4-I10","t":"înregistrări ale monitorizării temperaturii și umidității pentru fiecare încăpere a farmaciei și înregistrări de temperatură pentru instalațiile frigorifice, completate la zi"},{"k":"S2.2-C1-R4-I11","t":"monitorizarea erorilor de prescriere a medicamentului la nivelul secției, realizată"},{"k":"S2.2-C1-R4-I12","t":"procedură de verificare la primirea condicilor de medicamente, pentru eliminarea erorilor de prescriere-transcriere la nivelul secțiilor, implementată"}]},{"n":"ORGANIZAREA ACTIVITĂȚII, FARMACIA SPITALULUI ASIGURĂ CONTINUITATEA APROVIZIONĂRII CU MEDICAMENTE SPECIFICE ACTIVITĂȚII SPITALULUI, CONFORM CERINȚELOR ECHIPELOR MEDICALE ,URMĂRIND PE ÎNTREG TRASEUL IMPLEMENTAREA PRINCIPIULUI TRASABILITĂȚII MEDICAMENTULUI","i":[{"k":"S2.2-C1-R5-I1","t":"activitatea de recepție este procedurată și implementată"},{"k":"S2.2-C1-R5-I2","t":"activitatea de aprovizionare specifică farmaciei și depozitare a medicamentelor este procedurată și implementată"},{"k":"S2.2-C1-R5-I3","t":"activitatea de eliberare a medicamentelor este procedurată și implementată"},{"k":"S2.2-C1-R5-I4","t":"activitatea de preparare a medicamentelor în farmacia de spital este procedurată și implementată"},{"k":"S2.2-C1-R5-I5","t":"circuitul medicamentelor eliberate și neutilizate este asigurat prin auditarea periodică a protocoalelor și procedurilor în concordanță cu cerințele practicii medicale"},{"k":"S2.2-C1-R5-I6","t":"activitatea de returnare a medicamentelor este procedurată și implementată"},{"k":"S2.2-C1-R5-I7","t":"activitatea de depozitare,casare și distrugere a medicamentelor expirate din farmacia de spital este procedurată și implementată și este auditată periodic"},{"k":"S2.2-C1-R5-I8","t":"activitatea de dizolvare, diluție pentru preparatele parenterale (soluții injectabile sau perfuzabile) se efectuează într-un spațiu aseptic, dedicat, special amenajat, de către asistentul desemnat din secție și este procedurată"},{"k":"S2.2-C1-R5-I9","t":"activitatea de dizolvare, diluție, efectuată în farmacie, pentru preparatele parenterale special desemnate de Comisia Medicamentului din Spital este procedurată şi supervizată de farmacistul clinician"}]},{"n":"BUNA PRACTICĂ ÎN DOMENIUL MEDICAL, OFERĂ CEL MAI BUN TRATAMENT POSIBIL PACIENTULUI PRIN RESPECTAREA UNOR CERINȚE SPECIFICE PRIVIND UTILIZAREA PSIHOTROPELOR ȘI STUPEFIANTELOR","i":[{"k":"S2.2-C1-R6-I1","t":"activitatea de recepție, depozitare, prescriere și eliberare a medicamentelor cu risc de a crea dependență -stupefiante și psihotrope ,de mare risc supuse unui control strict (ex.amfetamină,metamfetamină) -sau substanțe sub control național (ex.ketamina), este procedurată și implementată"},{"k":"S2.2-C1-R6-I2","t":"activitatea de recepție, depozitare, prescriere și eliberare pentru medicamente care sunt supuse controlului -a preparatelor cu substanțe stupefiante (ex.codeina,dihidrocodeina,etilmorfina) și -a psihotropelor (ex.alprazolam,nitrazepam,midazolam,diazepam) este procedurată și implementată"},{"k":"S2.2-C1-R6-I3","t":"administrarea medicamentelor de mare risc stupefiante și psihotrope (ex.amfetamină,metamfetamină) supuse unui control strict sau a substanțelor sub control național (ex.ketamina) se face sub supravegherea medicului"}]},{"n":"BUNA PRACTICĂ ÎN DOMENIUL MEDICAL, OFERĂ CEL MAI BUN TRATAMENT POSIBIL PACIENTULUI PRIN RESPECTAREA UNOR CERINȚE SPECIFICE PRIVIND UTILIZAREA CITOSTATICELOR","i":[{"k":"S2.2-C1-R7-I1","t":"activitatea de dizolvare, diluție a medicamentelor citostatice în spital, în farmacie sau pe secții este procedurată și implementată"},{"k":"S2.2-C1-R7-I2","t":"activitatea de preparare a diluțiilor sterile cu citostatice, se realizeaza doar în locuri special amenajate,in farmacia sau pe sectii respectand regulile de bună practică de fabricație"},{"k":"S2.2-C1-R7-I3","t":"schema de tratament înregistrată în registrul de evidență dizolvări pentru medicamentele sterile și evaluată"},{"k":"S2.2-C1-R7-I4","t":"circuitul de protecție al personalului care prepară medicamente citotoxice este implementat"},{"k":"S2.2-C1-R7-I5","t":"circuitul de protecție al personalului care administrează substanțe citotoxice este implementat"},{"k":"S2.2-C1-R7-I6","t":"medicamentele,solvenții,soluțiille perfuzabile utilizate la prepararea soluțiilor sterile înregistrate în programul de gestiune cantitativ valorică al farmaciei ,conform protocolului de dizolvare/diluție la zi"},{"k":"S2.2-C1-R7-I7","t":"farmacistul clinician monitorizeza procedura de preparare a diluțiilor"},{"k":"S2.2-C1-R7-I8","t":"etichetarea si ambalarea preparatului steril corespunzătoare"},{"k":"S2.2-C1-R7-I9","t":"temperatura și perioada de păstrare, dacă administrarea nu este imediată 2- 8 grade respectată"}]},{"n":"BUNA PRACTICĂ ÎN DOMENIUL MEDICAL, OFERĂ CEL MAI BUN TRATAMENT POSIBIL PACIENTULUI PRIN RESPECTAREA UNOR CERINȚE SPECIFICE PRIVIND UTILIZAREA SOLUȚIILOR CONCENTRATE DE ELECTROLIȚI","i":[{"k":"S2.2-C1-R8-I1","t":"depozitarea soluțiilor concentrate de electroliți implică existența unui spațiu bine delimitat la nivelul farmaciei, separat de cel al depozitării celorlalte soluții perfuzabile și este semnalizată"},{"k":"S2.2-C1-R8-I2","t":"diluția soluțiilor concentrate de electroliți este procedurată iar păstrarea pâna la administrarea lor este de cel mult 24 ore"},{"k":"S2.2-C1-R8-I3","t":"prescripția și monitorizarea administrării soluțiilor concentrate de electroliți trebuie să includă determinări ale ionogramei, determinări ale echilibrului hidroelectrolitic și acido-bazic"},{"k":"S2.2-C1-R8-I4","t":"precauțiile la administrarea soluțiilor concentrate de electroliți sunt precizate de medicul prescriptor in FOCG, ritmul de administrare este controlat"},{"k":"S2.2-C1-R8-I5","t":"există o analiză a incompatibilităților medicamentoase și a asocierii substanță medicamentoasă /solvent făcută la nivel de spital și adusă la cunoștința prescriptorilor înainte de administrare"}]},{"n":"BUNA PRACTICĂ ÎN DOMENIUL MEDICAL OFERĂ CEL MAI BUN TRATAMENT POSIBIL PACIENTULUI PRIN RESPECTAREA UNOR CERINȚE SPECIFICE PRIVIND UTILIZAREA ANTIBIOTICELOR","i":[{"k":"S2.2-C1-R9-I1","t":"lista validată a antibioticelor cu distribuție controlată, pentru a limita utilizarea necorespunzătoare a antibioticelor cu spectru larg"},{"k":"S2.2-C1-R9-I2","t":"stocul curent al farmaciei spitalului conține în permanență antibioticele uzuale"},{"k":"S2.2-C1-R9-I3","t":"există o listă validată de antibiotice utilizate cu o frecvență mai redusă, cu indicații specifice de utilizare a căror prescriere este avizată de medicul șef"},{"k":"S2.2-C1-R9-I4","t":"achiziționarea antibioticelor cu frecvență redusă facută punctual și în timp util, fără a pune în pericol siguranța pacientului și prescrierea lor este avizată de medicul șef"},{"k":"S2.2-C1-R9-I5","t":"protocoalele privind antibioterapia aplicate în funcție de tipul de patologie"},{"k":"S2.2-C1-R9-I6","t":"prescrierea antibioticelor este limitată în funcție de competență și specificul serviciului clinic"},{"k":"S2.2-C1-R9-I7","t":"asocierile de antibiotice se fac în situații bine fundamentate de existența unor infecții severe,fiind documentate microbiologic"},{"k":"S2.2-C1-R9-I8","t":"în asocierile de antibiotice se respectă regula nu se asociază 2 antibiotice din acceași clasă, 2 antibiotice cu spectru larg, 2 antibiotice cu efecte adverse asupra aceluiași organ"},{"k":"S2.2-C1-R9-I9","t":"Prescrierea antibioticelor este reglementata la nivelul spitalului"},{"k":"S2.2-C1-R9-I10","t":"practica medicală la nivel de spital prevede analiza si consemnarea in FO a evolutiei sub tratament antibiotic la 48-72 ore"},{"k":"S2.2-C1-R9-I11","t":"este respectată cerința specifică în alegerea antibioticului,recoltarea probelor microbiologice se face înaintea instituirii oricărei antibioterapii"},{"k":"S2.2-C1-R9-I12","t":"decizia privind administrarea unui antibiotic, chiar de la prima oră, în infecții severe argumentată În FOCG"},{"k":"S2.2-C1-R9-I13","t":"rezultatele antibiogramei și antifungigramei, existente în FOCG stau la baza conducerii antibioterapiei și antifungiterapiei"},{"k":"S2.2-C1-R9-I14","t":"număr de cazuri la care s-a instalat rezistența la cefalosporine din generația a III-a din totalul cazurilor avand indicatii de tratament, în ultimul an calendaristic incheiat"},{"k":"S2.2-C1-R9-I15","t":"număr de cazuri tratate cu carbapeneme din totalul cazurilor tratate cu antibiotice în ultimul semestru calendaristic incheiat"},{"k":"S2.2-C1-R9-I16","t":"structuri organizatorice la nivel de spital cu rol în monitorizarea și asigurarea regulilor de bună practică în domeniul antibioterapiei Consiliul medical, Comisia medicamentului, SSCIN"},{"k":"S2.2-C1-R9-I17","t":"există la nivelul Consiliul medical,Comisia medicamentului,SSCIN o analiză a consumului de antibiotice trimestrială în funcție de natura activității fiecărui serviciu clinic"},{"k":"S2.2-C1-R9-I18","t":"există o monitorizare permanentă privind respectarea procedurilor și protocoalelor privind antibioterapia și a eficienței și eficacității lor"},{"k":"S2.2-C1-R9-I19","t":"circuitul antibioticelor eliberate și neutilizate asigurat prin auditarea periodică în concordanță cu cerințele practicii medicale"},{"k":"S2.2-C1-R9-I20","t":"abordarea multidisciplinară a antibioterapiei în infecțiile severe în echipa formată de clinician,infecționist,epidemiolog,,farmacist clinician este o practică curentă a spitalului"}]},{"n":"COMUNICAREA FARMACIEI SPITALULUI CU ECHIPA MEDICALĂ CERINȚĂ DE BAZĂ ÎN ASIGURAREA UNEI BUNE PRACTICI ÎN ANTIBIOTERAPIE","i":[{"k":"S2.2-C1-R10-I1","t":"lista de antibiotice disponibile la un moment dat, actualizată cel puțin odată pe an și validată, accesibilă informatic echipei medicale"},{"k":"S2.2-C1-R10-I2","t":"informațile accesibile informatic permit prescrierea corectă a antibioticelor privind recomandarea,rezistența bacteriană ,apariția unor reacții secundare sau adverse"},{"k":"S2.2-C1-R10-I3","t":"farmacia spitalului pune la dispoziția echipei medicale evaluări de farmacovigilență și farmacoepidemiologice"},{"k":"S2.2-C1-R10-I4","t":"farmacia spitalului informează medicii și asistentele cu privire la buna practică în administrarea antibioticului"},{"k":"S2.2-C1-R10-I5","t":"sistem de informare a personalului medical cu privire la rezultatele auditului clinic cu privire la antibioterapie"},{"k":"S2.2-C1-R10-I6","t":"sistem de informare a personalului medical cu privire la noile antibiotice introduse în spital"},{"k":"S2.2-C1-R10-I7","t":"farmacia spitalului asigură transmiterea costurilor tratamentelor prescrise pe servicii medicale către toate părțile implicate în monitorizarea trasabilității antibioticului"},{"k":"S2.2-C1-R10-I8","t":"utilizarea antibioticelor în spital, analizată la nivelul farmaciei pe clase de antibiotice și transmisă periodic structurilor funcționale ale spitalului"}]}]}]},{"c":"2.3","d":"2","n":"Managementul infecțiilor asociate asistenței și îngrijirilor medicale și antibioticorezistenţei constituie un obiectiv major al asigurării siguranţei pacientului şi personalului medico -sanitar.","r":[{"n":"Conducerea spitalului îşi asumă atribuţii pentru coordonarea şi controlul riscului infecţios rezultat din activităţile spitalului","e":[{"n":"Şefii sectoarelor de activitate sunt responsabili pentru implementarea programului de supraveghere, prevenire şi combatere a infecţiilor asociate îngrijirilor medicale","i":[{"k":"S2.3-C1-R1-I1","t":"Analiză documentată a unor cazuri suspecte de infecţie nosocomială, conform definiţiilor de caz, cu directă colaborare a medicilor curanţi."},{"k":"S2.3-C1-R1-I2","t":"Consimţământul informat al pacientului anexat FOCG, prezintă distinct riscul infecţios asociat asistenţei şi îngrijirilor medicale"},{"k":"S2.3-C1-R1-I3","t":"Număr cazuri externate cu diagnostic de infecţie nosocomială menţionat în FOCG"}]},{"n":"Spitalul alocă resurse pentru supravegherea, prevenirea şi combaterea infecțiilor nosocomiale","i":[{"k":"S2.3-C1-R2-I1","t":"Necesarul de produse biocide, antiseptice şi dezinfectanţi de nivel înalt, materiale consumabile de laborator pentru recoltare si prelucrare de probe, evaluat de SSCIN şi Laboratorul de microbiologie"},{"k":"S2.3-C1-R2-I2","t":"Achiziţia produselor biocide, antiseptice şi dezinfectanţi de nivel înalt respectă cerinţele tehnice elaborate de SSCIN"},{"k":"S2.3-C1-R2-I3","t":"Cerinţele tehnice formulate pentru achiziţia produselor biocide, antiseptice, dezinfectanţi de nivel înalt, respectă legislaţia sanitară, standardele ASRO armonizate UE şi Registrul Naţional al Produselor biocide"},{"k":"S2.3-C1-R2-I4","t":"Produsele achiziţionate la nivelul spitalului pentru acţiunile de prevenire si combatere a infecţiilor nosocomiale corespund nevoilor estimate tehnic şi cantitativ de SSCIN"},{"k":"S2.3-C1-R2-I5","t":"Produsele biocide achiziţionate, însoţite de Fişa de securitate"}]}]},{"n":"Coordonarea acţiunilor de supraveghere, prevenţie şi control a infecţiilor asociate asistenţei şi îngrijirilor medicale este realizată de o structură adaptată mărimii şi complexităţii spitalului","e":[{"n":"Este aprobată structura şi funcţionarea SSCIN","i":[{"k":"S2.3-C2-R1-I1","t":"Încadrare SSCIN cu personal conform legislaţiei sanitare în vigoare"},{"k":"S2.3-C2-R1-I2","t":"Incadrare asistent de igienă sau asistent medical desemnat cu atribuţii specifice SSCIN"},{"k":"S2.3-C2-R1-I3","t":"Agent DDD în structura SSCIN"}]},{"n":"Spitalul aprobă portofoliul SSCIN ce cuprinde documentaţia specifică domeniului de activitate","i":[{"k":"S2.3-C2-R2-I1","t":"Plan de activitate SSCIN, pe anul în curs, elaborat şi aprobat"},{"k":"S2.3-C2-R2-I2","t":"Plan de acţiune dezinfecţie-dezinsecţie-deratizare (DDD) pe spital, pe anul în curs, aprobat"},{"k":"S2.3-C2-R2-I3","t":"Planificare sistem de autocontrol bacteriologic pentru evaluarea eficienţei operaţiunilor de curăţenie, dezinfecţie şi sterilizare, pe anul în curs, aprobată"},{"k":"S2.3-C2-R2-I4","t":"Planul propriu SSCIN pentru instruirea personalului sanitar, pe sectoare de activitate, pe anul în curs, elaborat"},{"k":"S2.3-C2-R2-I5","t":"Cartea de vizită a unităţii, cu prezentarea caracteristicilor funcţionale şi structurale, elaborată"},{"k":"S2.3-C2-R2-I6","t":"Harta punctelor şi segmentelor de risc, cu identificarea zonelor şi a practicilor medicale la risc"},{"k":"S2.3-C2-R2-I7","t":"Istoricul şi tendinţa evoluţiei infecţiilor nosocomiale, actualizate pentru anul calendaristic încheiat"},{"k":"S2.3-C2-R2-I8","t":"Ghid de prevenire al infecţiilor nosocomiale şi de bune practici epidemiologice, elaborat."},{"k":"S2.3-C2-R2-I9","t":"Procedură operaţională: Metode şi tehnici privind operaţiunile de curăţenie şi dezinfecţie, în mediul spitalicesc"},{"k":"S2.3-C2-R2-I10","t":"Procedura operaţională: Gestionarea şi utilizarea produselor biocide, a materialelor şi echipamentelor destinate efectuării operaţiunilor de curăţenie şi dezinfecţie, în mediul spitalicesc"},{"k":"S2.3-C2-R2-I11","t":"Procedura operaţională: Activitatea DDD (Dezinfecţie - Dezinsecţie - Deratizare)"},{"k":"S2.3-C2-R2-I12","t":"Procedură operaţională: Pregătirea materialelor sanitare şi a dispozitivelor medicale în vederea sterilizării şi monitorizarea operaţiunilor de sterilizare propriu -zise."},{"k":"S2.3-C2-R2-I13","t":"Procedură operaţională: Supravegherea, monitorizarea şi raportarea bolilor transmisibile cu potenţial nosocomial"},{"k":"S2.3-C2-R2-I14","t":"Procedură operaţională: Organizarea serviciului spălătorie al spitalului"},{"k":"S2.3-C2-R2-I15","t":"Procedură operaţională: Sistemul de gestionare al deşeurilor rezultate din activităţile medicale"},{"k":"S2.3-C2-R2-I16","t":"Procedură operaţională: Identificarea, comunicarea şi raportarea cazurilor de infecţii asociate asistenţei şi îngrijirilor medicale"},{"k":"S2.3-C2-R2-I17","t":"Procedura operaţională: Precauţiunile standard şi modalităţile de intervenţie în caz de expunere ocupaţională a personalului la agenţi contaminanţi"},{"k":"S2.3-C2-R2-I18","t":"Procedura operaţională: Autocontrolul bacteriologic, activitate de apreciere şi monitorizare a eficienţei operaţiunilor de curăţenie, dezinfecţie şi sterilizare."},{"k":"S2.3-C2-R2-I19","t":"Procedura operaţională: Controlul riscului infecţios în circuitele funcţionale ale spitalului."}]},{"n":"SSCIN asigură circuitul informaţional al activităţii de supraveghere a bolilor transmisibile şi IN","i":[{"k":"S2.3-C2-R3-I1","t":"Plan de activitate SSCIN adaptat pe secţii/sectoare de activitate privind reperele activităţii de supraveghere a bolilor transmisibile şi IN în funcţie de harta de risc 